      "proposed_laureates": [
        "Albrecht Karle",
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrinos as a new observational channel for the Universe, a major advance in astroparticle physics.",
        "attribution": "Halzen's scientific leadership and Karle's central role in the detector and collaboration make a strong case, though the discovery was built by a large international team.",
        "maturity": "The diffuse astrophysical flux is firmly established; source identification is progressing and will determine how far this window can take us.",
        "uncertainties": [
          "The origin of most of the measured neutrino flux is still unresolved.",
          "Individual credit is challenging for a large detector collaboration."
        ]
      }
    },
