      "proposed_laureates": [
        "Fabiola Gianotti",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson completed a central part of the Standard Model and required extraordinary detectors and analysis.",
        "attribution": "The named leaders represent ATLAS and CMS contributions, but the discovery is inseparable from thousands of collaborators; any individual selection is necessarily incomplete.",
        "maturity": "The particle and its properties have been confirmed over many years of measurements, making the discovery exceptionally mature.",
        "uncertainties": [
          "The main uncertainty is fair recognition of the collective experimental work within a prize that can name only a few people."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Jean-Loup Puget"
      ],
      "assessment": {
        "nobel_worthiness": "Precision maps of the microwave background revealed the acoustic structure of the early Universe and established a quantitative foundation for modern cosmology.",
        "attribution": "These names span major observational and theoretical contributions, although the achievement drew on several missions and broad international teams.",
        "maturity": "Independent measurements and decades of consistency with cosmological observations make the core result highly mature.",
        "uncertainties": [
          "The discovery is a sequence of contributions, so the boundaries of the prize-worthy advance and the individuals central to it need careful definition."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "James M. Lattimer"
      ],
      "assessment": {
        "nobel_worthiness": "Connecting neutron-star mergers to heavy-element production united gravitational-wave, electromagnetic, and nuclear astrophysics in a landmark result.",
        "attribution": "The proposed names represent key theoretical and modeling contributions; the observational discovery itself involved extensive teams across multiple facilities.",
        "maturity": "The 2017 multi-messenger event gave compelling support, but the relative contribution of mergers to the cosmic r-process inventory remains under study.",
        "uncertainties": [
          "The result is still developing, and the full population of r-process sites is not settled.",
          "Credit spans predictions, modeling, and large observational collaborations."
        ]
      }
    },
    {
