      "ballot_id": "B045",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enable tests of fundamental physics through unprecedented control of atomic transitions.",
        "attribution": "Katori and Ye are clearly associated with the key independent approaches and their experimental realization.",
        "maturity": "The clocks are now highly developed and independently replicated, with continuing improvements in accuracy and applications.",
        "uncertainties": [
          "Whether the central achievement should be recognized now or after a further landmark redefinition of the second is a matter of timing."
        ]
      }
    },
