      "assessment": {
        "nobel_worthiness": "Fast radio bursts revealed an unexpected class of energetic cosmic transients and created a productive new field of radio astronomy.",
        "attribution": "The discovery team is identifiable and the credited names reflect the observation and its early analysis.",
        "maturity": "The phenomenon is well established and repeating sources have broadened the field, but the population and physical mechanisms remain unsettled.",
        "uncertainties": [
          "The long-term physical significance of FRBs is not yet clear enough to judge the full scale of the discovery."
        ]
      }
    },
